const resultsSection = document.getElementById('results');

quizForm.addEventListener('submit', (e) => {
  e.preventDefault();

  // Validate that at least one checkbox is selected for each question
  const questions = ['question1', 'question2', 'question3'];
  let isValid = true;

  questions.forEach((question, index) => {
    const questionNumber = index + 1;
    const checkboxes = document.querySelectorAll(`input[name="${question}"]:checked`);
    const errorElement = document.getElementById(`q${questionNumber}-error`);

    if (checkboxes.length === 0) {
      isValid = false;
      errorElement.textContent = `Error: Please select at least one answer for Question ${questionNumber}.`;
      errorElement.hidden = false;

      if (index === 0) {
        // Focus on first unanswered question
        document.getElementById(`q${questionNumber}-a`).focus();
      }
    } else {
      errorElement.hidden = true;
      errorElement.textContent = '';
    }
  });

  if (isValid) {
    // Collect responses
    const responses = {};
    questions.forEach((question) => {
      const checked = Array.from(
        document.querySelectorAll(`input[name="${question}"]:checked`)
      ).map((cb) => cb.value);
      responses[question] = checked;
    });

    console.log('Quiz responses:', responses);

    // Show results
    quizForm.hidden = true;
    resultsSection.hidden = false;
    resultsSection.focus();
  }
});

// Clear error when user interacts with checkbox
document.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => {
  checkbox.addEventListener('change', () => {
    const fieldset = checkbox.closest('fieldset');
